      "when": "Keep it running while you sleep",
      "steps": [
        "Set to high mode before bed",
        "Close bedroom doors",
        "Keep windows shut"
      ]
    },
    {
      "actionId": "n95_for_open_transport",
      "title": "Wear N95 for travel",
      "why": "An N95 mask can reduce your inhaled pollution by {{impact.n95_for_open_transport.pct}} during commutes.",
      "when": "Whenever you are outdoors or in open vehicles",
      "steps": [
        "Ensure a tight seal",
        "Replace mask if damp",
        "Avoid touching the front"
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Damp mop instead of sweeping",
      "why": "Sweeping kicks up settled dust. Damp mopping reduces indoor particulate matter by {{impact.damp_mop_dont_sweep.pct}}.",
      "when": "During your daily cleaning routine",
      "steps": [
        "Use a wet cloth or mop",
        "Avoid dry brooms",
        "Wipe surfaces with a damp rag"
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Schedule errands wisely",
      "why": "Moving outdoor tasks to the best window reduces exposure by {{impact.errands_in_best_window.pct}}.",
      "when": "Between {{best.start}} and {{best.end}}",
      "steps": [
        "Plan trips early",
        "Combine multiple stops",
        "Avoid the {{avoid.start}} to {{avoid.end}} window"
      ]
    },
    {
      "actionId": "avoid_indoor_smoke_sources",
      "title": "Eliminate indoor smoke",
      "why": "Avoiding incense, candles, or smoking reduces indoor pollutants by {{impact.avoid_indoor_smoke_sources.pct}}.",
      "when": "Throughout the day",
      "steps": [
        "Stop burning incense",
        "Avoid using candles",
        "Ensure kitchen is vented"
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for no burning",
      "why": "Discouraging waste burning in your area can lower local PM2.5 by {{impact.community_no_burning.pct}}.",
      "when": "If you see smoke nearby",
      "steps": [
        "Politely inform neighbors",
        "Suggest waste collection",
        "Report illegal burning"
      ]
    }
  ],
  "memberNotes": [
